	port.CellsDrop(b, 0)
	m = pdfcrypt.CrDecrypt(mode, st, kn, port.CellsBytes(a), 0, n, b)
	i = 0
	for i < m {
		v = port.CellsAt(b, i)
		pdflex.PlStrSetByte(ar, h, i, v)
		i += 1
	}
	pdflex.PlStrSetLen(ar, h, m)
	return 0
